		if v, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok {
			resolved.rightDelim = v
		}
	}
	if !flags.Changed("experimental") {
		if v, ok := os.LookupEnv("GOMPLATE_EXPERIMENTAL"); ok {
			if b, err := strconv.ParseBool(v); err == nil {
				resolved.experimental = b
			}
		}
	}

	configPath := resolved.configPath
	if !flags.Changed("config") {
		if v, ok := os.LookupEnv("GOMPLATE_CONFIG"); ok {
			configPath = v
		}
	}
	resolved.configPath = configPath

	cfg, err := readConfigFile(configPath, flags.Changed("config") || os.Getenv("GOMPLATE_CONFIG") != "")
	if err != nil {
		return nil, err
	}
	if cfg != nil {
		if err := applyConfig(resolved, cfg, flags); err != nil {
			return nil, err
		}
	}

	if err := validateOptions(resolved, flags); err != nil {
		if isRuntimeError(err) {
			return nil, &quietError{err: err}
		}
		return nil, err
	}

	for i := range resolved.inputFiles {
		if resolved.inputFiles[i] != "-" {
			resolved.inputFiles[i] = filepath.Clean(resolved.inputFiles[i])
		}
	}
	for i := range resolved.outputFiles {
		if resolved.outputFiles[i] != "-" {
			resolved.outputFiles[i] = filepath.Clean(resolved.outputFiles[i])
		}
	}

	return resolved, nil
}

func applyConfig(resolved *resolvedOptions, cfg *configFile, flags flagChecker) error {
	inputOverride := ""
	switch {
	case flags.Changed("in"):
		inputOverride = "in"
	case flags.Changed("input-dir"):
		inputOverride = "dir"
	case flags.Changed("file"):
		inputOverride = "file"
	}

	if inputOverride == "" || inputOverride == "in" {
		if !flags.Changed("in") && cfg.In != "" {
			resolved.inline = cfg.In
		}
	}
	if inputOverride == "" || inputOverride == "file" {
		if !flags.Changed("file") && len(cfg.InputFiles) > 0 {
			resolved.inputFiles = append([]string(nil), cfg.InputFiles...)
			resolved.inputFilesExplicit = true
		}
		if !flags.Changed("out") && len(cfg.OutputFiles) > 0 {
			resolved.outputFiles = append([]string(nil), cfg.OutputFiles...)
			resolved.outputFilesExplicit = true
		}
	}
	if inputOverride == "" || inputOverride == "dir" {
		if !flags.Changed("input-dir") && cfg.InputDir != "" {
			resolved.inputDir = cfg.InputDir
		}
		if !flags.Changed("output-dir") && cfg.OutputDir != "" {
			resolved.outputDir = cfg.OutputDir
		}
		if !flags.Changed("output-map") && cfg.OutputMap != "" {
			resolved.outputMap = cfg.OutputMap
		}
		if !flags.Changed("exclude") && len(cfg.Excludes) > 0 {
			resolved.excludes = append([]string(nil), cfg.Excludes...)
		}
		if !flags.Changed("exclude-processing") && len(cfg.ExcludeProcessing) > 0 {
			resolved.excludeProcessing = append([]string(nil), cfg.ExcludeProcessing...)
		}
		if !flags.Changed("include") && len(cfg.Includes) > 0 {
			resolved.includes = append([]string(nil), cfg.Includes...)
		}
	}

	if !flags.Changed("left-delim") && cfg.LeftDelim != "" {
		resolved.leftDelim = cfg.LeftDelim
	}
	if !flags.Changed("right-delim") && cfg.RightDelim != "" {
		resolved.rightDelim = cfg.RightDelim
	}
	if !flags.Changed("missing-key") && cfg.MissingKey != "" {
		resolved.missingKey = cfg.MissingKey
	}
	if !flags.Changed("chmod") && cfg.Chmod != "" {
		resolved.chmod = cfg.Chmod
	}
	if !flags.Changed("exec-pipe") && cfg.ExecPipe != nil {
		resolved.execPipe = *cfg.ExecPipe
	}
	if !flags.Changed("experimental") && cfg.Experimental != nil {
		resolved.experimental = *cfg.Experimental
	}

	if !flags.Changed("datasource") {
		resolved.datasources = flattenSourceMap(cfg.Datasources)
	}
	if !flags.Changed("context") {
		resolved.contexts = flattenSourceMap(cfg.Context)
	}
	if !flags.Changed("datasource-header") {
		resolved.datasourceHeaders = append(flattenHeaders(cfg.Datasources), flattenHeaders(cfg.Context)...)
	}
	if !flags.Changed("template") {
		resolved.templates = flattenSourceMap(cfg.Templates)
	}
	if !flags.Changed("plugin") && len(cfg.Plugins) > 0 {
		resolved.plugins = map[string]pluginConfig{}
		for name, plugin := range cfg.Plugins {
			resolved.plugins[name] = plugin
		}
	}
	if len(resolved.postExec) == 0 && len(cfg.PostExec) > 0 {
		resolved.postExec = append([]string(nil), cfg.PostExec...)
	}

	return nil
}

func validateOptions(opts *resolvedOptions, flags flagChecker) error {
	activeModes := make([]string, 0, 3)

	if strings.TrimSpace(opts.inline) != "" {
		activeModes = append(activeModes, "in")
	}
	if opts.inputDir != "" {
		activeModes = append(activeModes, "inputDir")
	}

	filesActive := opts.inputFilesExplicit
	if !opts.inputFilesExplicit && len(activeModes) == 0 {
		filesActive = true
	}
	if filesActive {
		activeModes = append(activeModes, "inputFiles")
	}

	if len(activeModes) > 1 {
		return fmt.Errorf("failed to validate config: only one of these options is supported at a time: %s", quoteList(activeModes))
	}

	if filesActive && len(opts.inputFiles) != len(opts.outputFiles) {
		return fmt.Errorf("failed to validate config: the number of input files must match the number of output files")
	}

	if opts.execPipe && len(opts.postExec) == 0 {
		return fmt.Errorf("failed to validate config: execPipe requires a postExec command")
	}
	if opts.execPipe && filesActive && len(opts.inputFiles) > 1 {
		return fmt.Errorf("failed to validate config: execPipe does not support multiple input files")
	}

	switch opts.missingKey {
	case "error", "default", "invalid", "zero":
	default:
		return fmt.Errorf("failed to validate config: unsupported missing-key mode %q", opts.missingKey)
	}

	_ = flags
	return nil
}

func isRuntimeError(err error) bool {
	msg := err.Error()
	return strings.Contains(msg, "renderTemplate:") ||
		strings.Contains(msg, "failed to gather templates") ||
		strings.Contains(msg, "failed to render directory") ||
		strings.Contains(msg, "failed to read datasource")
}

func quoteList(items []string) string {
	quoted := make([]string, len(items))
	for i, item := range items {
		quoted[i] = fmt.Sprintf("'%s'", item)
	}
	return strings.Join(quoted, ", ")
}

func flattenSourceMap(m map[string]sourceConfig) []string {
	if len(m) == 0 {
		return nil
	}
	keys := make([]string, 0, len(m))
	for key := range m {
		keys = append(keys, key)
	}
	sortStrings(keys)
	out := make([]string, 0, len(keys))
	for _, key := range keys {
		out = append(out, fmt.Sprintf("%s=%s", key, m[key].URL))
	}
	return out
}

func flattenHeaders(m map[string]sourceConfig) []string {
	if len(m) == 0 {
		return nil
	}
	keys := make([]string, 0)
	for alias, cfg := range m {
		for header, values := range cfg.Header {
			for _, value := range values {
				keys = append(keys, fmt.Sprintf("%s=%s: %s", alias, header, value))
			}
		}
	}
	sortStrings(keys)
	return keys
}

type flagChecker interface {
	Changed(name string) bool
}

