package main

import (
	"errors"
	"fmt"
	"os"

	"gopkg.in/yaml.v3"
)

type configFile struct {
	In                string                  `yaml:"in"`
	InputDir          string                  `yaml:"inputDir"`
	InputFiles        []string                `yaml:"inputFiles"`
	OutputDir         string                  `yaml:"outputDir"`
	OutputFiles       []string                `yaml:"outputFiles"`
	OutputMap         string                  `yaml:"outputMap"`
	LeftDelim         string                  `yaml:"leftDelim"`
	RightDelim        string                  `yaml:"rightDelim"`
	MissingKey        string                  `yaml:"missingKey"`
	Chmod             string                  `yaml:"chmod"`
	ExecPipe          *bool                   `yaml:"execPipe"`
	Experimental      *bool                   `yaml:"experimental"`
	Excludes          []string                `yaml:"excludes"`
	ExcludeProcessing []string                `yaml:"excludeProcessing"`
	Includes          []string                `yaml:"includes"`
	Datasources       map[string]sourceConfig `yaml:"datasources"`
	Context           map[string]sourceConfig `yaml:"context"`
	Templates         map[string]sourceConfig `yaml:"templates"`
	Plugins           map[string]pluginConfig `yaml:"plugins"`
	PostExec          stringListOrScalar      `yaml:"postExec"`
}

type sourceConfig struct {
	URL    string              `yaml:"url"`
	Header map[string][]string `yaml:"header"`
}

type stringListOrScalar []string

func (s *stringListOrScalar) UnmarshalYAML(node *yaml.Node) error {
	switch node.Kind {
	case yaml.ScalarNode:
		var value string
		if err := node.Decode(&value); err != nil {
			return err
		}
		*s = []string{value}
		return nil
	case yaml.SequenceNode:
		var values []string
		if err := node.Decode(&values); err != nil {
			return err
		}
		*s = values
		return nil
	default:
		return fmt.Errorf("unsupported YAML node for string list")
	}
}

func (s *sourceConfig) UnmarshalYAML(node *yaml.Node) error {
	switch node.Kind {
	case yaml.ScalarNode:
		var value string
		if err := node.Decode(&value); err != nil {
			return err
		}
		s.URL = value
		return nil
	case yaml.MappingNode:
		type plain sourceConfig
		var value plain
		if err := node.Decode(&value); err != nil {
			return err
		}
		*s = sourceConfig(value)
		return nil
	default:
		return fmt.Errorf("unsupported YAML node for datasource")
	}
}

func (p *pluginConfig) UnmarshalYAML(node *yaml.Node) error {
	switch node.Kind {
	case yaml.ScalarNode:
		var value string
		if err := node.Decode(&value); err != nil {
			return err
		}
		p.Cmd = value
		return nil
	case yaml.MappingNode:
		type plain pluginConfig
		var value plain
		if err := node.Decode(&value); err != nil {
			return err
		}
		*p = pluginConfig(value)
		return nil
	default:
		return fmt.Errorf("unsupported YAML node for plugin")
	}
}

func readConfigFile(path string, explicit bool) (*configFile, error) {
	if path == "" {
		return nil, nil
	}

	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) && !explicit && path == ".gomplate.yaml" {
			return nil, nil
		}
		if explicit {
			return nil, fmt.Errorf("config file requested, but couldn't be opened: %w", err)
		}
		return nil, nil
	}

	cfg := &configFile{}
	if err := yaml.Unmarshal(data, cfg); err != nil {
		return nil, fmt.Errorf("failed to parse config: %w", err)
	}
	return cfg, nil
}

