package main

import (
	"encoding/base64"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func sortStrings(values []string) {
	sort.Strings(values)
}

func splitKV(spec string, requireValue bool) (string, string, error) {
	before, after, ok := strings.Cut(spec, "=")
	if ok {
		if before == "" {
			return "", "", fmt.Errorf("missing alias in %q", spec)
		}
		if requireValue && after == "" {
			return "", "", fmt.Errorf("missing value in %q", spec)
		}
		return before, after, nil
	}
	if requireValue {
		return "", "", fmt.Errorf("expected alias=value form: %q", spec)
	}
	return spec, "", nil
}

func parseAliasValue(spec string) (string, string, error) {
	if alias, value, ok := strings.Cut(spec, "="); ok {
		if alias == "" {
			return "", "", fmt.Errorf("missing alias in %q", spec)
		}
		return alias, value, nil
	}

	if filepath.IsAbs(spec) {
		return "", "", fmt.Errorf("must provide an alias with files not in working directory")
	}

	alias := inferAlias(spec)
	return alias, spec, nil
}

func inferAlias(spec string) string {
	base := filepath.Base(spec)
	ext := filepath.Ext(base)
	if ext != "" {
		base = strings.TrimSuffix(base, ext)
	}
	return base
}

func readEnv(name string, defaults ...string) string {
	if value := os.Getenv(name); value != "" {
		return value
	}
	if fileValue := os.Getenv(name + "_FILE"); fileValue != "" {
		data, err := os.ReadFile(fileValue)
		if err == nil {
			return strings.TrimRight(string(data), "\r\n")
		}
	}
	if len(defaults) > 0 {
		return defaults[0]
	}
	return ""
}

func expandEnv(input string) string {
	return os.Expand(input, func(name string) string {
		return readEnv(name)
	})
}

func parseURLMaybe(raw string) (*url.URL, bool) {
	if raw == "" {
		return nil, false
	}
	u, err := url.Parse(raw)
	if err != nil {
		return nil, false
	}
	if u.Scheme == "" {
		return nil, false
	}
	return u, true
}

func withinWorkingDir(path string) bool {
	cwd, err := os.Getwd()
	if err != nil {
		return false
	}
	absPath, err := filepath.Abs(path)
	if err != nil {
		return false
	}
	absCwd, err := filepath.Abs(cwd)
	if err != nil {
		return false
	}
	rel, err := filepath.Rel(absCwd, absPath)
	if err != nil {
		return false
	}
	return rel == "." || (!strings.HasPrefix(rel, ".."+string(os.PathSeparator)) && rel != "..")
}

func base64DecodeString(s string) (string, error) {
	decoded, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		return "", err
	}
	return string(decoded), nil
}

