+}
+
+func (m *datasourceManager) load(ctx context.Context, alias, subpath string) (*loadedSource, error) {
+	def, err := m.resolveDefinition(alias)
+	if err != nil {
+		return nil, err
+	}
+	target, err := applySubpath(def.Target, subpath)
+	if err != nil {
+		return nil, err
+	}
+
+	cacheKey := alias + "\x00" + subpath
+	m.mu.Lock()
+	if loaded, ok := m.cache[cacheKey]; ok {
+		m.mu.Unlock()
+		return loaded, nil
+	}
+	m.mu.Unlock()
+
+	raw, contentType, err := m.fetchRaw(ctx, def, target)
+	if err != nil {
+		return nil, err
+	}
+	value, err := parseSourceValue(target, raw, contentType)
+	if err != nil {
+		return nil, fmt.Errorf("failed to read datasource %s: %w", alias, err)
+	}
+	loaded := &loadedSource{Raw: raw, Value: value, ContentType: contentType}
+
+	m.mu.Lock()
+	m.cache[cacheKey] = loaded
+	m.mu.Unlock()
+	return loaded, nil
+}
+
+func (m *datasourceManager) resolveDefinition(alias string) (sourceDefinition, error) {
+	if def, ok := m.defs[alias]; ok {
+		return def, nil
+	}
+	if _, ok := parseURLMaybe(alias); ok {
+		return sourceDefinition{Alias: alias, Target: alias, Headers: http.Header{}}, nil
+	}
+	if _, err := os.Stat(alias); err == nil {
+		return sourceDefinition{Alias: alias, Target: alias, Headers: http.Header{}}, nil
+	}
+	return sourceDefinition{}, fmt.Errorf("undefined datasource %q", alias)
+}
+
+func (m *datasourceManager) fetchRaw(ctx context.Context, def sourceDefinition, target string) ([]byte, string, error) {
+	if u, ok := parseURLMaybe(target); ok {
+		switch u.Scheme {
+		case "http", "https":
+			req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
+			if err != nil {
+				return nil, "", err
+			}
+			for name, values := range def.Headers {
+				for _, value := range values {
+					req.Header.Add(name, value)
+				}
+			}
+			resp, err := m.client.Do(req)
+			if err != nil {
+				return nil, "", err
+			}
+			defer resp.Body.Close()
+			if resp.StatusCode < 200 || resp.StatusCode >= 300 {
+				return nil, "", fmt.Errorf("unexpected status %s", resp.Status)
+			}
+			body, err := io.ReadAll(resp.Body)
+			if err != nil {
+				return nil, "", err
+			}
+			return body, resp.Header.Get("Content-Type"), nil
+		case "file":
+			filename := u.Path
+			if filename == "" {
+				filename = u.Opaque
+			}
+			return readPathRaw(filename)
+		case "env":
+			key := strings.TrimPrefix(u.Path, "/")
+			if key == "" {
+				key = strings.TrimPrefix(u.Opaque, "/")
+			}
+			return []byte(readEnv(key)), "text/plain", nil
+		case "stdin":
+			return append([]byte(nil), m.stdinData...), "text/plain", nil
+		default:
+			return nil, "", fmt.Errorf("unsupported datasource scheme %q", u.Scheme)
+		}
+	}
+
+	return readPathRaw(target)
+}
+
+func readPathRaw(name string) ([]byte, string, error) {
+	info, err := os.Stat(name)
+	if err != nil {
+		return nil, "", err
+	}
+	if info.IsDir() {
+		entries, err := os.ReadDir(name)
+		if err != nil {
+			return nil, "", err
+		}
+		names := make([]string, 0, len(entries))
+		for _, entry := range entries {
+			names = append(names, entry.Name())
+		}
+		data, err := json.Marshal(names)
+		return data, "application/array+json", err
+	}
+	data, err := os.ReadFile(name)
+	if err != nil {
+		return nil, "", err
+	}
+	return data, detectType(name, ""), nil
+}
+
+func applySubpath(target, subpath string) (string, error) {
+	if subpath == "" {
+		return target, nil
+	}
+	if u, ok := parseURLMaybe(target); ok {
+		switch u.Scheme {
+		case "http", "https", "file":
+			base := u.Path
+			if base == "" {
+				base = u.Opaque
+			}
+			base = strings.TrimSuffix(base, "/")
+			u.Path = path.Join(base, strings.TrimPrefix(subpath, "/"))
+			u.RawPath = u.Path
+			u.Opaque = ""
+			return u.String(), nil
+		case "env":
+			key := strings.TrimPrefix(u.Path, "/")
+			if key == "" {
+				key = strings.TrimPrefix(u.Opaque, "/")
+			}
+			key = path.Join(strings.TrimSuffix(key, "/"), strings.TrimPrefix(subpath, "/"))
+			u.Path = "/" + key
+			u.Opaque = ""
+			return u.String(), nil
+		default:
+			return "", fmt.Errorf("datasource subpaths unsupported for %q", u.Scheme)
+		}
+	}
+
+	if strings.HasSuffix(target, string(os.PathSeparator)) {
+		return filepath.Join(target, subpath), nil
+	}
+	if info, err := os.Stat(target); err == nil && info.IsDir() {
+		return filepath.Join(target, subpath), nil
+	}
+	return filepath.Join(filepath.Dir(target), subpath), nil
+}
+
+func parseSourceValue(name string, raw []byte, contentType string) (any, error) {
+	switch detectType(name, contentType) {
+	case "application/json", "application/array+json":
+		var value any
+		if err := json.Unmarshal(raw, &value); err != nil {
+			return nil, err
+		}
+		return value, nil
+	case "application/yaml":
+		var value any
+		if err := yaml.Unmarshal(raw, &value); err != nil {
+			return nil, err
+		}
+		return normalizeYAML(value), nil
+	case "application/toml":
+		var value any
+		if err := toml.Unmarshal(raw, &value); err != nil {
+			return nil, err
+		}
+		return value, nil
+	case "text/csv":
+		rows, err := csv.NewReader(bytes.NewReader(raw)).ReadAll()
+		if err != nil {
+			return nil, err
+		}
+		out := make([][]string, len(rows))
+		copy(out, rows)
+		return out, nil
+	case "application/x-env":
+		return parseDotEnv(raw), nil
+	default:
+		return string(raw), nil
+	}
+}
+
+func detectType(name, contentType string) string {
+	u, ok := parseURLMaybe(name)
+	if ok {
+		query := u.Query()
+		typeParam := os.Getenv("GOMPLATE_TYPE_PARAM")
+		if typeParam == "" {
+			typeParam = "type"
+		}
+		if override := query.Get(typeParam); override != "" {
+			return cleanContentType(override)
+		}
+	}
+
+	if contentType != "" {
+		return cleanContentType(contentType)
+	}
+
+	ext := strings.ToLower(filepath.Ext(name))
+	switch ext {
+	case ".json":
+		return "application/json"
+	case ".yaml", ".yml":
+		return "application/yaml"
+	case ".toml":
+		return "application/toml"
+	case ".csv":
+		return "text/csv"
+	case ".env":
+		return "application/x-env"
+	default:
+		return "text/plain"
+	}
+}
+
+func cleanContentType(contentType string) string {
+	before, _, _ := strings.Cut(contentType, ";")
+	return strings.TrimSpace(strings.ToLower(before))
+}
+
+func normalizeYAML(value any) any {
+	switch v := value.(type) {
+	case map[string]any:
+		for key, item := range v {
+			v[key] = normalizeYAML(item)
+		}
+		return v
+	case map[any]any:
+		out := map[string]any{}
+		for key, item := range v {
+			out[fmt.Sprint(key)] = normalizeYAML(item)
+		}
+		return out
+	case []any:
+		for i, item := range v {
+			v[i] = normalizeYAML(item)
+		}
+		return v
+	default:
+		return value
+	}
+}
+
+func parseDotEnv(raw []byte) map[string]string {
+	out := map[string]string{}
+	lines := strings.Split(strings.ReplaceAll(string(raw), "\r\n", "\n"), "\n")
+	for _, line := range lines {
+		line = strings.TrimSpace(line)
+		if line == "" || strings.HasPrefix(line, "#") {
+			continue
+		}
+		line = strings.TrimPrefix(line, "export ")
+		key, value, ok := strings.Cut(line, "=")
+		if !ok {
+			continue
+		}
+		key = strings.TrimSpace(key)
+		value = strings.TrimSpace(value)
+		switch {
+		case strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\""):
+			value = strings.Trim(value, "\"")
+			value = expandEnv(strings.ReplaceAll(value, `\n`, "\n"))
+			value = strings.ReplaceAll(value, `\t`, "\t")
+		case strings.HasPrefix(value, "'") && strings.HasSuffix(value, "'"):
+			value = strings.Trim(value, "'")
+		default:
+			value = expandEnv(value)
+		}
+		out[key] = value
+	}
+	return out
+}
+
+func buildRootContext(ctx context.Context, mgr *datasourceManager, specs []string) (any, error) {
+	root := map[string]any{
+		"Env": currentEnvMap(),
+	}
+	for _, spec := range specs {
+		alias, _, err := parseAliasValue(spec)
+		if err != nil {
+			return nil, err
+		}
+		value, err := mgr.Load(ctx, alias, "")
+		if err != nil {
+			return nil, err
+		}
+		if alias == "." {
+			root = nil
+			return value, nil
+		}
+		root[alias] = value
+	}
+	return root, nil
+}
+
+func currentEnvMap() map[string]string {
+	out := map[string]string{}
+	for _, entry := range os.Environ() {
+		key, value, ok := strings.Cut(entry, "=")
+		if ok {
+			out[key] = value
+		}
+	}
+	return out
+}
+
+func gatherTemplateInput(name string, stdin []byte) ([]byte, error) {
+	if name == "-" {
+		return append([]byte(nil), stdin...), nil
+	}
+	return os.ReadFile(name)
+}
+
+func gatherAllStdin(required bool) ([]byte, error) {
+	if !required {
+		return nil, nil
+	}
+	data, err := io.ReadAll(os.Stdin)
+	if err != nil {
+		return nil, err
+	}
+	return data, nil
+}
+
+func loadTemplateRefs(ctx context.Context, specs []string, mgr *datasourceManager) ([]templateAsset, error) {
+	assets := make([]templateAsset, 0)
+	for _, spec := range specs {
+		alias, value, err := parseAliasValue(spec)
+		if err != nil {
+			return nil, err
+		}
+
+		if u, ok := parseURLMaybe(value); ok && (u.Scheme == "http" || u.Scheme == "https") {
+			def := sourceDefinition{Alias: alias, Target: value, Headers: http.Header{}}
+			raw, _, err := mgr.fetchRaw(ctx, def, value)
+			if err != nil {
+				return nil, err
+			}
+			assets = append(assets, templateAsset{Name: alias, Content: string(raw)})
+			continue
+		}
+
+		info, err := os.Stat(value)
+		if err != nil {
+			return nil, err
+		}
+		if info.IsDir() {
+			err = filepath.WalkDir(value, func(path string, d os.DirEntry, err error) error {
+				if err != nil {
+					return err
+				}
+				if d.IsDir() {
+					return nil
+				}
+				raw, err := os.ReadFile(path)
+				if err != nil {
+					return err
+				}
+				rel, err := filepath.Rel(value, path)
+				if err != nil {
+					return err
+				}
+				name := alias + "/" + filepath.ToSlash(rel)
+				assets = append(assets, templateAsset{Name: name, Content: string(raw)})
+				return nil
+			})
+			if err != nil {
+				return nil, err
+			}
+			continue
+		}
+		raw, err := os.ReadFile(value)
+		if err != nil {
+			return nil, err
+		}
+		assets = append(assets, templateAsset{Name: alias, Content: string(raw)})
+	}
+
+	sort.Slice(assets, func(i, j int) bool {
+		return assets[i].Name < assets[j].Name
+	})
+	return assets, nil
+}
+
+func matchAny(patterns []string, name string) bool {
+	for _, pattern := range patterns {
+		matched, err := matchPattern(pattern, name)
+		if err == nil && matched {
+			return true
+		}
+	}
+	return false
+}
+
+func matchPattern(pattern, name string) (bool, error) {
+	if pattern == "" {
+		return false, nil
+	}
+	if strings.HasPrefix(pattern, "/") {
+		pattern = strings.TrimPrefix(pattern, "/")
+	}
+	return filepath.Match(pattern, filepath.Base(name))
+}
+
+func walkInputDir(root string) ([]string, error) {
+	var files []string
+	err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
+		if err != nil {
+			return err
+		}
+		if d.IsDir() {
+			return nil
+		}
+		files = append(files, path)
+		return nil
+	})
+	return files, err
+}
+
+func shouldCopyWithoutProcessing(rel string, patterns []string) bool {
+	return matchAny(patterns, rel)
+}
+
+func shouldExclude(rel string, includes, excludes []string) bool {
+	if len(includes) > 0 && !matchAny(includes, rel) {
+		return true
+	}
+	return matchAny(excludes, rel)
