package main

import (
	"bytes"
	"context"
	"fmt"
	"log/slog"
	"os/exec"
	"path/filepath"
	"strings"
	"text/template"
	"time"
)

type templateAsset struct {
	Name    string
	Content string
}

type templateRenderer struct {
	opts      *resolvedOptions
	manager   *datasourceManager
	logger    *slog.Logger
	templates []templateAsset
}

type templateRef struct {
	t        *template.Template
	root     any
	mainPath string
}

func newTemplateRenderer(ctx context.Context, opts *resolvedOptions, manager *datasourceManager, logger *slog.Logger) (*templateRenderer, error) {
	templates, err := loadTemplateRefs(ctx, opts.templates, manager)
	if err != nil {
		return nil, fmt.Errorf("failed to gather templates for rendering: %w", err)
	}
	return &templateRenderer{
		opts:      opts,
		manager:   manager,
		logger:    logger,
		templates: templates,
	}, nil
}

func (r *templateRenderer) render(ctx context.Context, name, mainPath, content string, root any) ([]byte, error) {
	ref := &templateRef{root: root, mainPath: mainPath}
	funcMap := r.funcMap(ctx, ref)

	t := template.New(name).
		Funcs(funcMap).
		Delims(r.opts.leftDelim, r.opts.rightDelim).
		Option(missingKeyOption(r.opts.missingKey))

	for _, asset := range r.templates {
		var err error
		t, err = t.New(asset.Name).Parse(rewriteTemplateNamespaces(asset.Content, r.opts.leftDelim, r.opts.rightDelim))
		if err != nil {
			return nil, fmt.Errorf("renderTemplate: parse template %s: %w", asset.Name, err)
		}
	}

	var err error
	t, err = t.Parse(rewriteTemplateNamespaces(content, r.opts.leftDelim, r.opts.rightDelim))
	if err != nil {
		return nil, fmt.Errorf("renderTemplate: parse template %s: %w", name, err)
	}
	ref.t = t

	var buf bytes.Buffer
	if err := t.ExecuteTemplate(&buf, name, root); err != nil {
		return nil, fmt.Errorf("renderTemplate: failed to render template %s: %w", name, err)
	}
	return buf.Bytes(), nil
}

func missingKeyOption(mode string) string {
	switch mode {
	case "zero":
		return "missingkey=zero"
	case "default", "invalid":
		return "missingkey=default"
	default:
		return "missingkey=error"
	}
}

func rewriteTemplateNamespaces(input, leftDelim, rightDelim string) string {
	if leftDelim == "" || rightDelim == "" {
		return input
	}

	var out strings.Builder
	for {
		start := strings.Index(input, leftDelim)
		if start < 0 {
			out.WriteString(input)
			break
		}
		out.WriteString(input[:start+len(leftDelim)])
		input = input[start+len(leftDelim):]

		end := strings.Index(input, rightDelim)
		if end < 0 {
			out.WriteString(input)
			break
		}
		action := input[:end]
		out.WriteString(rewriteAction(action))
		out.WriteString(rightDelim)
		input = input[end+len(rightDelim):]
	}
	return out.String()
}

func rewriteAction(action string) string {
	namespaces := []string{
		"aws", "base64", "coll", "conv", "crypto", "data", "env", "file", "filepath", "gcp",
		"math", "net", "path", "random", "regexp", "semver", "sockaddr", "strings", "test",
		"time", "tmpl", "uuid",
	}
	for _, namespace := range namespaces {
		action = rewriteNamespace(action, namespace)
	}
	return action
}

func rewriteNamespace(action, namespace string) string {
	var out strings.Builder
	for i := 0; i < len(action); i++ {
		if !strings.HasPrefix(action[i:], namespace+".") {
			out.WriteByte(action[i])
			continue
		}
		if i > 0 {
			prev := action[i-1]
			if prev == '.' || prev == '$' || prev == '_' || (prev >= '0' && prev <= '9') || (prev >= 'A' && prev <= 'Z') || (prev >= 'a' && prev <= 'z') {
				out.WriteByte(action[i])
				continue
			}
		}

		j := i + len(namespace) + 1
		for j < len(action) {
			ch := action[j]
			if ch == '_' || (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') {
				j++
				continue
			}
			break
		}
		if j == i+len(namespace)+1 {
			out.WriteByte(action[i])
			continue
		}
		out.WriteString(namespace)
		out.WriteByte('_')
		out.WriteString(action[i+len(namespace)+1 : j])
		i = j - 1
	}
	return out.String()
}

func (r *templateRenderer) funcMap(ctx context.Context, ref *templateRef) template.FuncMap {
	funcs := baseFuncMap()
	funcs["datasource"] = func(args ...any) (any, error) {
		return r.datasource(ctx, args...)
	}
	funcs["ds"] = funcs["datasource"]
	funcs["include"] = func(args ...any) (string, error) {
		return r.include(ctx, args...)
	}
	funcs["datasourceExists"] = func(alias string) bool {
		return r.manager.Exists(alias)
	}
	funcs["datasourceReachable"] = func(alias string) bool {
		return r.manager.Reachable(ctx, alias)
	}
	funcs["listDatasources"] = func() []string {
		return r.manager.List()
	}
	funcs["defineDatasource"] = func(alias, target string) string {
		r.manager.Define(alias, target)
		return ""
	}
	funcs["env_Env"] = func() map[string]string {
		return currentEnvMap()
	}
	funcs["tmpl_Path"] = func() string {
		return ref.mainPath
	}
	funcs["tmpl_PathDir"] = func() string {
		dir := filepath.Dir(ref.mainPath)
		if dir == "" {
			return "."
		}
		return dir
	}
	funcs["tmpl_Exec"] = func(args ...any) (string, error) {
		return r.execTemplate(ref, args...)
	}
	funcs["tmpl_Inline"] = func(args ...any) (string, error) {
		return r.inlineTemplate(ctx, ref, args...)
	}
	funcs["tpl"] = funcs["tmpl_Inline"]

	for name, plugin := range r.opts.plugins {
		funcs[name] = r.pluginFunc(ctx, plugin)
	}

	return funcs
}

func (r *templateRenderer) datasource(ctx context.Context, args ...any) (any, error) {
	if len(args) == 0 || len(args) > 2 {
		return nil, fmt.Errorf("wrong number of args for datasource")
	}
	alias := fmt.Sprint(args[0])
	subpath := ""
	if len(args) == 2 {
		subpath = fmt.Sprint(args[1])
	}
	return r.manager.Load(ctx, alias, subpath)
}

func (r *templateRenderer) include(ctx context.Context, args ...any) (string, error) {
	if len(args) == 0 || len(args) > 2 {
		return "", fmt.Errorf("wrong number of args for include")
	}
	alias := fmt.Sprint(args[0])
	subpath := ""
	if len(args) == 2 {
		subpath = fmt.Sprint(args[1])
	}
	return r.manager.Include(ctx, alias, subpath)
}

func (r *templateRenderer) execTemplate(ref *templateRef, args ...any) (string, error) {
	if len(args) == 0 || len(args) > 2 {
		return "", fmt.Errorf("wrong number of args for tmpl.Exec")
	}
	name := fmt.Sprint(args[0])
	context := ref.root
	if len(args) == 2 {
		context = args[1]
	}
	var buf bytes.Buffer
	if err := ref.t.ExecuteTemplate(&buf, name, context); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (r *templateRenderer) inlineTemplate(ctx context.Context, ref *templateRef, args ...any) (string, error) {
	if len(args) == 0 {
		return "", fmt.Errorf("wrong number of args for tmpl.Inline")
	}

	name := ""
	templateText := ""
	context := ref.root
	switch len(args) {
	case 1:
		templateText = fmt.Sprint(args[0])
	case 2:
		templateText = fmt.Sprint(args[0])
		context = args[1]
	case 3:
		name = fmt.Sprint(args[0])
		templateText = fmt.Sprint(args[1])
		context = args[2]
	default:
		return "", fmt.Errorf("wrong number of args for tmpl.Inline")
	}
	if name == "" {
		name = fmt.Sprintf("__inline_%d", time.Now().UnixNano())
	}

	t, err := ref.t.New(name).Parse(rewriteTemplateNamespaces(templateText, r.opts.leftDelim, r.opts.rightDelim))
	if err != nil {
		return "", err
	}
	ref.t = t

	var buf bytes.Buffer
	if err := ref.t.ExecuteTemplate(&buf, name, context); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (r *templateRenderer) pluginFunc(ctx context.Context, plugin pluginConfig) func(args ...any) (string, error) {
	return func(args ...any) (string, error) {
		timeout := 5 * time.Second
		if plugin.Timeout != "" {
			if d, err := time.ParseDuration(plugin.Timeout); err == nil {
				timeout = d
			}
		}
		pctx, cancel := context.WithTimeout(ctx, timeout)
		defer cancel()

		allArgs := make([]string, 0, len(plugin.Args)+len(args))
		allArgs = append(allArgs, plugin.Args...)
		var stdin string
		for i, arg := range args {
			if plugin.Pipe && i == len(args)-1 {
				stdin = fmt.Sprint(arg)
				continue
			}
			allArgs = append(allArgs, fmt.Sprint(arg))
		}

		cmd := exec.CommandContext(pctx, plugin.Cmd, allArgs...)
		if plugin.Pipe {
			cmd.Stdin = strings.NewReader(stdin)
		}
		var stdout, stderr bytes.Buffer
		cmd.Stdout = &stdout
		cmd.Stderr = &stderr
		if err := cmd.Run(); err != nil {
			if stderr.Len() > 0 {
				return "", fmt.Errorf("%w: %s", err, strings.TrimSpace(stderr.String()))
			}
			return "", err
		}
		return strings.TrimRight(stdout.String(), "\r\n"), nil
	}
}

