+			return parsedNumber{isFloat: true, f: f}, nil
+		}
+		i, err := strconv.ParseInt(s, 0, 64)
+		if err != nil {
+			return parsedNumber{}, err
+		}
+		return parsedNumber{i: i}, nil
+	default:
+		return parsedNumber{}, fmt.Errorf("unable to convert %T to number", v)
+	}
+}
