+func mathAdd(args ...any) (any, error) {
+	var totalInt int64
+	var totalFloat float64
+	floatMode := false
+	for _, arg := range args {
+		n, err := parseNumber(arg)
+		if err != nil {
+			return nil, err
+		}
+		if n.isFloat {
+			if !floatMode {
+				totalFloat = float64(totalInt)
+				floatMode = true
+			}
+			totalFloat += n.f
+			continue
+		}
+		if floatMode {
+			totalFloat += float64(n.i)
+		} else {
+			totalInt += n.i
+		}
+	}
+	if floatMode {
+		return totalFloat, nil
+	}
+	return totalInt, nil
+}
