+func mathDiv(a, b any) (float64, error) {
+	an, err := parseNumber(a)
+	if err != nil {
+		return 0, err
+	}
+	bn, err := parseNumber(b)
+	if err != nil {
+		return 0, err
+	}
+	divisor := numberToFloat(bn)
+	if divisor == 0 {
+		return 0, fmt.Errorf("divide by zero")
+	}
+	return numberToFloat(an) / divisor, nil
