+	bn, err := parseNumber(b)
+	if err != nil {
+		return nil, err
+	}
+	result := stdmath.Pow(numberToFloat(an), numberToFloat(bn))
+	if an.isFloat || bn.isFloat {
+		return result, nil
+	}
+	return int64(result), nil
