+func mathMax(args ...any) (any, error) {
+	if len(args) == 0 {
+		return nil, fmt.Errorf("math.Max requires at least one argument")
+	}
+	max := args[0]
+	for _, arg := range args[1:] {
+		a, _ := parseNumber(max)
+		b, err := parseNumber(arg)
+		if err != nil {
+			return nil, err
+		}
+		if numberToFloat(b) > numberToFloat(a) {
