+func collHas(needle, haystack any) bool {
+	switch h := haystack.(type) {
+	case string:
+		return strings.Contains(h, fmt.Sprint(needle))
+	}
+	value := reflect.ValueOf(haystack)
+	switch value.Kind() {
+	case reflect.Map:
+		key := reflect.ValueOf(needle)
+		return value.MapIndex(key).IsValid()
+	case reflect.Slice, reflect.Array:
+		for i := 0; i < value.Len(); i++ {
+			if reflect.DeepEqual(value.Index(i).Interface(), needle) {
+				return true
+			}
+		}
+	}
+	return false
+}
+
+func collIndex(args ...any) (any, error) {
+	if len(args) < 2 {
+		return nil, fmt.Errorf("coll.Index requires at least two arguments")
+	}
+	current := reflect.ValueOf(args[0])
+	for _, keyArg := range args[1:] {
+		if !current.IsValid() {
+			return nil, fmt.Errorf("missing value")
+		}
+		switch current.Kind() {
+		case reflect.Map:
+			key := reflect.ValueOf(keyArg)
+			next := current.MapIndex(key)
+			if !next.IsValid() {
+				return nil, fmt.Errorf("missing map key %v", keyArg)
+			}
+			current = next
+		case reflect.Slice, reflect.Array:
+			index, err := toInt(keyArg)
+			if err != nil {
+				return nil, err
+			}
+			if index < 0 || index >= current.Len() {
+				return nil, fmt.Errorf("index out of range")
+			}
+			current = current.Index(index)
+		default:
+			return nil, fmt.Errorf("can not index %s", current.Kind())
+		}
+	}
+	return current.Interface(), nil
+}
