+		return "", fmt.Errorf("assertion failed")
+	}
+	return "", fmt.Errorf(strings.Join(msg, " "))
+}
+
+func testFail(msg ...string) (string, error) {
+	if len(msg) == 0 {
+		return "", fmt.Errorf("failure requested")
+	}
+	return "", fmt.Errorf(strings.Join(msg, " "))
+}
