+func timeParse(args ...any) (time.Time, error) {
+	switch len(args) {
+	case 1:
+		return time.Parse(time.RFC3339, fmt.Sprint(args[0]))
+	case 2:
+		return time.Parse(fmt.Sprint(args[0]), fmt.Sprint(args[1]))
+	default:
+		return time.Time{}, fmt.Errorf("time.Parse requires 1 or 2 arguments")
+	}
+}
+
+func timeParseLocal(args ...any) (time.Time, error) {
+	switch len(args) {
+	case 1:
+		return time.ParseInLocation(time.RFC3339, fmt.Sprint(args[0]), time.Local)
+	case 2:
+		return time.ParseInLocation(fmt.Sprint(args[0]), fmt.Sprint(args[1]), time.Local)
+	default:
+		return time.Time{}, fmt.Errorf("time.ParseLocal requires 1 or 2 arguments")
+	}
+}
+
+func timeParseInLocation(location, layout, input string) (time.Time, error) {
+	loc, err := time.LoadLocation(location)
+	if err != nil {
+		return time.Time{}, err
+	}
+	return time.ParseInLocation(layout, input, loc)
+}
+
+func timeUnix(args ...any) (time.Time, error) {
+	switch len(args) {
+	case 1:
+		sec, err := toInt64(args[0])
+		if err != nil {
+			return time.Time{}, err
+		}
+		return time.Unix(sec, 0), nil
+	case 2:
+		sec, err := toInt64(args[0])
+		if err != nil {
+			return time.Time{}, err
+		}
+		nsec, err := toInt64(args[1])
+		if err != nil {
+			return time.Time{}, err
+		}
+		return time.Unix(sec, nsec), nil
+	default:
+		return time.Time{}, fmt.Errorf("time.Unix requires 1 or 2 arguments")
+	}
+}
