+func netParseAddr(s string) (netip.Addr, error) {
+	addr, err := netip.ParseAddr(s)
+	if err != nil {
+		return netip.Addr{}, fmt.Errorf("ParseAddr(%q): unable to parse IP", s)
+	}
+	return addr, nil
+}
