+func semverCheckConstraint(constraint string, version any) (bool, error) {
+	c, err := semverpkg.NewConstraint(constraint)
+	if err != nil {
+		return false, err
+	}
+	var v *semverpkg.Version
+	switch x := version.(type) {
+	case *semverpkg.Version:
+		v = x
+	case string:
+		v, err = semverpkg.NewVersion(x)
+	default:
+		v, err = semverpkg.NewVersion(fmt.Sprint(version))
+	}
+	if err != nil {
+		return false, err
+	}
+	return c.Check(v), nil
+}
