+func toSlice(v any) ([]any, error) {
+	switch x := v.(type) {
+	case []any:
+		return append([]any(nil), x...), nil
+	case []string:
+		out := make([]any, len(x))
+		for i, item := range x {
+			out[i] = item
+		}
+		return out, nil
+	case []int:
+		out := make([]any, len(x))
+		for i, item := range x {
+			out[i] = item
+		}
+		return out, nil
+	case []int64:
+		out := make([]any, len(x))
+		for i, item := range x {
+			out[i] = item
+		}
+		return out, nil
+	case []float64:
+		out := make([]any, len(x))
+		for i, item := range x {
+			out[i] = item
+		}
+		return out, nil
+	}
+	rv := reflect.ValueOf(v)
+	if !rv.IsValid() {
+		return nil, nil
+	}
+	if rv.Kind() != reflect.Slice && rv.Kind() != reflect.Array {
+		return nil, fmt.Errorf("value is not a slice")
+	}
+	out := make([]any, rv.Len())
+	for i := 0; i < rv.Len(); i++ {
+		out[i] = rv.Index(i).Interface()
+	}
+	return out, nil
+}
+
+func toStringSlice(v any) ([]string, error) {
+	items, err := toSlice(v)
+	if err != nil {
+		return nil, err
+	}
+	out := make([]string, len(items))
+	for i, item := range items {
+		out[i] = fmt.Sprint(item)
+	}
+	return out, nil
+}
+
+func toStringRows(v any) ([][]string, error) {
+	items, err := toSlice(v)
+	if err != nil {
+		return nil, err
+	}
+	rows := make([][]string, len(items))
+	for i, item := range items {
+		rows[i], err = toStringSlice(item)
+		if err != nil {
+			return nil, err
+		}
+	}
+	return rows, nil
+}
+
+func isEmptyValue(v any) bool {
+	if v == nil {
+		return true
+	}
+	switch x := v.(type) {
+	case string:
+		return x == ""
+	case bool:
+		return !x
+	case int, int8, int16, int32, int64:
+		return reflect.ValueOf(v).Int() == 0
+	case uint, uint8, uint16, uint32, uint64:
+		return reflect.ValueOf(v).Uint() == 0
+	case float32, float64:
+		return reflect.ValueOf(v).Float() == 0
+	}
+	rv := reflect.ValueOf(v)
+	switch rv.Kind() {
+	case reflect.Array, reflect.Map, reflect.Slice, reflect.String:
+		return rv.Len() == 0
+	case reflect.Bool:
+		return !rv.Bool()
+	case reflect.Interface, reflect.Pointer:
+		return rv.IsNil()
+	}
+	return false
+}
