type parsedNumber struct {
	isFloat bool
	f       float64
	i       int64
}

func parseNumber(v any) (parsedNumber, error) {
	switch n := v.(type) {
	case int:
		return parsedNumber{i: int64(n)}, nil
	case int8:
		return parsedNumber{i: int64(n)}, nil
	case int16:
		return parsedNumber{i: int64(n)}, nil
	case int32:
		return parsedNumber{i: int64(n)}, nil
	case int64:
		return parsedNumber{i: n}, nil
	case uint:
		return parsedNumber{i: int64(n)}, nil
	case uint8:
		return parsedNumber{i: int64(n)}, nil
	case uint16:
		return parsedNumber{i: int64(n)}, nil
	case uint32:
		return parsedNumber{i: int64(n)}, nil
	case uint64:
		return parsedNumber{i: int64(n)}, nil
	case float32:
		return parsedNumber{isFloat: true, f: float64(n)}, nil
	case float64:
		return parsedNumber{isFloat: true, f: n}, nil
	case json.Number:
		return parseNumber(string(n))
	case string:
		s := strings.TrimSpace(n)
		if s == "" {
			return parsedNumber{}, fmt.Errorf("unable to convert empty string to number")
		}
		if looksFloat(s) {
			f, err := strconv.ParseFloat(s, 64)
			if err != nil {
				return parsedNumber{}, err
			}
			return parsedNumber{isFloat: true, f: f}, nil
		}
		i, err := strconv.ParseInt(s, 0, 64)
		if err != nil {
			return parsedNumber{}, err
		}
		return parsedNumber{i: i}, nil
	default:
		return parsedNumber{}, fmt.Errorf("unable to convert %T to number", v)
	}
}

func looksFloat(s string) bool {
	s = strings.TrimSpace(s)
	if strings.EqualFold(s, "nan") || strings.EqualFold(s, "inf") || strings.EqualFold(s, "+inf") || strings.EqualFold(s, "-inf") {
		return true
	}
	return strings.ContainsAny(s, ".eE")
}

func mathAdd(args ...any) (any, error) {
	var totalInt int64
	var totalFloat float64
	floatMode := false
	for _, arg := range args {
		n, err := parseNumber(arg)
		if err != nil {
			return nil, err
		}
		if n.isFloat {
			if !floatMode {
				totalFloat = float64(totalInt)
				floatMode = true
			}
			totalFloat += n.f
			continue
		}
		if floatMode {
			totalFloat += float64(n.i)
		} else {
			totalInt += n.i
		}
	}
	if floatMode {
		return totalFloat, nil
	}
	return totalInt, nil
}

func mathSub(a, b any) (any, error) {
	an, err := parseNumber(a)
	if err != nil {
		return nil, err
	}
	bn, err := parseNumber(b)
	if err != nil {
		return nil, err
	}
	if an.isFloat || bn.isFloat {
		return numberToFloat(an) - numberToFloat(bn), nil
	}
	return an.i - bn.i, nil
}

func mathMul(args ...any) (any, error) {
	totalInt := int64(1)
	totalFloat := 1.0
	floatMode := false
	for _, arg := range args {
		n, err := parseNumber(arg)
		if err != nil {
			return nil, err
		}
		if n.isFloat {
			if !floatMode {
				totalFloat = float64(totalInt)
				floatMode = true
			}
			totalFloat *= n.f
			continue
		}
		if floatMode {
			totalFloat *= float64(n.i)
		} else {
			totalInt *= n.i
		}
	}
	if floatMode {
		return totalFloat, nil
	}
	return totalInt, nil
}

func mathDiv(a, b any) (float64, error) {
	an, err := parseNumber(a)
	if err != nil {
		return 0, err
	}
	bn, err := parseNumber(b)
	if err != nil {
		return 0, err
	}
	divisor := numberToFloat(bn)
	if divisor == 0 {
		return 0, fmt.Errorf("divide by zero")
	}
	return numberToFloat(an) / divisor, nil
}

func mathPow(a, b any) (any, error) {
	an, err := parseNumber(a)
	if err != nil {
		return nil, err
	}
	bn, err := parseNumber(b)
	if err != nil {
		return nil, err
	}
	result := stdmath.Pow(numberToFloat(an), numberToFloat(bn))
	if an.isFloat || bn.isFloat {
		return result, nil
	}
	return int64(result), nil
}

func mathRem(a, b any) (int64, error) {
	an, err := parseNumber(a)
	if err != nil {
		return 0, err
	}
	bn, err := parseNumber(b)
	if err != nil {
		return 0, err
	}
	if an.isFloat || bn.isFloat {
		return 0, fmt.Errorf("remainder requires integers")
	}
	if bn.i == 0 {
		return 0, fmt.Errorf("divide by zero")
	}
	return an.i % bn.i, nil
}

func mathSeq(args ...any) ([]int64, error) {
	var start, end, step int64
	switch len(args) {
	case 1:
		start, end, step = 1, mustInt64(args[0]), 1
	case 2:
		start, end, step = mustInt64(args[0]), mustInt64(args[1]), 1
	case 3:
		start, end, step = mustInt64(args[0]), mustInt64(args[1]), mustInt64(args[2])
	default:
		return nil, fmt.Errorf("wrong number of args for seq")
	}
	return math.Seq(start, end, step), nil
}

