func mathMax(args ...any) (any, error) {
	if len(args) == 0 {
		return nil, fmt.Errorf("math.Max requires at least one argument")
	}
	max := args[0]
	for _, arg := range args[1:] {
		a, _ := parseNumber(max)
		b, err := parseNumber(arg)
		if err != nil {
			return nil, err
		}
		if numberToFloat(b) > numberToFloat(a) {
			max = arg
		}
	}
	n, _ := parseNumber(max)
	if n.isFloat {
		return n.f, nil
	}
	return n.i, nil
}

func mathMin(args ...any) (any, error) {
	if len(args) == 0 {
		return nil, fmt.Errorf("math.Min requires at least one argument")
	}
	min := args[0]
	for _, arg := range args[1:] {
		a, _ := parseNumber(min)
		b, err := parseNumber(arg)
		if err != nil {
			return nil, err
		}
		if numberToFloat(b) < numberToFloat(a) {
			min = arg
		}
	}
	n, _ := parseNumber(min)
	if n.isFloat {
		return n.f, nil
	}
	return n.i, nil
}

func mathIsFloat(v any) bool {
