	switch first := args[0].(type) {
	case string:
		sep = first
		items = args[1]
	default:
		items = args[0]
		sep = fmt.Sprint(args[1])
	}
	values, err := toStringSlice(items)
	if err != nil {
		return "", err
	}
	return strings.Join(values, sep), nil
