func collDict(args ...any) map[string]any {
	out := map[string]any{}
	for i := 0; i < len(args); i += 2 {
		key := fmt.Sprint(args[i])
		value := any("")
		if i+1 < len(args) {
			value = args[i+1]
		}
		out[key] = value
	}
