func collGoSlice(args ...any) (any, error) {
	if len(args) < 2 || len(args) > 3 {
		return nil, fmt.Errorf("coll.GoSlice requires 2 or 3 arguments")
	}
	value := reflect.ValueOf(args[0])
	if value.Kind() != reflect.Slice && value.Kind() != reflect.Array && value.Kind() != reflect.String {
		return nil, fmt.Errorf("coll.GoSlice requires a slice, array, or string")
	}
	start, err := toInt(args[1])
	if err != nil {
		return nil, err
	}
	end := value.Len()
	if len(args) == 3 {
		end, err = toInt(args[2])
		if err != nil {
			return nil, err
		}
	}
	return value.Slice(start, end).Interface(), nil
}

func collHas(needle, haystack any) bool {
	switch h := haystack.(type) {
	case string:
		return strings.Contains(h, fmt.Sprint(needle))
	}
	value := reflect.ValueOf(haystack)
	switch value.Kind() {
	case reflect.Map:
		key := reflect.ValueOf(needle)
		return value.MapIndex(key).IsValid()
	case reflect.Slice, reflect.Array:
		for i := 0; i < value.Len(); i++ {
			if reflect.DeepEqual(value.Index(i).Interface(), needle) {
				return true
			}
		}
	}
	return false
}

func collIndex(args ...any) (any, error) {
	if len(args) < 2 {
		return nil, fmt.Errorf("coll.Index requires at least two arguments")
	}
	current := reflect.ValueOf(args[0])
	for _, keyArg := range args[1:] {
		if !current.IsValid() {
			return nil, fmt.Errorf("missing value")
		}
		switch current.Kind() {
		case reflect.Map:
			key := reflect.ValueOf(keyArg)
			next := current.MapIndex(key)
			if !next.IsValid() {
				return nil, fmt.Errorf("missing map key %v", keyArg)
			}
			current = next
		case reflect.Slice, reflect.Array:
			index, err := toInt(keyArg)
			if err != nil {
				return nil, err
			}
			if index < 0 || index >= current.Len() {
				return nil, fmt.Errorf("index out of range")
			}
			current = current.Index(index)
		default:
			return nil, fmt.Errorf("can not index %s", current.Kind())
		}
	}
	return current.Interface(), nil
}

func collKeys(v any) ([]string, error) {
	value := reflect.ValueOf(v)
	if value.Kind() != reflect.Map {
		return nil, fmt.Errorf("coll.Keys requires a map")
	}
	keys := make([]string, 0, value.Len())
	for _, key := range value.MapKeys() {
		keys = append(keys, fmt.Sprint(key.Interface()))
	}
	sort.Strings(keys)
	return keys, nil
}

func collValues(v any) ([]any, error) {
	keys, err := collKeys(v)
	if err != nil {
		return nil, err
	}
	value := reflect.ValueOf(v)
	out := make([]any, 0, len(keys))
	for _, key := range keys {
		out = append(out, value.MapIndex(reflect.ValueOf(key)).Interface())
	}
	return out, nil
}

