func collUniq(v any) ([]any, error) {
	items, err := toSlice(v)
	if err != nil {
		return nil, err
	}
	out := make([]any, 0, len(items))
	for _, item := range items {
		if !collHas(item, out) {
			out = append(out, item)
		}
	}
	return out, nil
}

func collFlatten(v any) ([]any, error) {
	items, err := toSlice(v)
	if err != nil {
		return nil, err
	}
	var out []any
	for _, item := range items {
		rv := reflect.ValueOf(item)
		if rv.IsValid() && (rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array) {
			sub, err := collFlatten(item)
			if err != nil {
				return nil, err
			}
			out = append(out, sub...)
			continue
		}
		out = append(out, item)
	}
	return out, nil
}

func collReverse(v any) ([]any, error) {
	items, err := toSlice(v)
	if err != nil {
		return nil, err
	}
	for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
		items[i], items[j] = items[j], items[i]
	}
	return items, nil
}

func collSort(v any) ([]any, error) {
	items, err := toSlice(v)
	if err != nil {
		return nil, err
	}
	sort.Slice(items, func(i, j int) bool {
		return fmt.Sprint(items[i]) < fmt.Sprint(items[j])
	})
	return items, nil
}

func collMerge(args ...any) (map[string]any, error) {
	out := map[string]any{}
	for _, arg := range args {
		m, ok := normalizeYAML(arg).(map[string]any)
		if !ok {
			return nil, fmt.Errorf("coll.Merge requires maps")
		}
		for key, value := range m {
			if existing, ok := out[key].(map[string]any); ok {
				if nested, ok := normalizeYAML(value).(map[string]any); ok {
					merged, err := collMerge(existing, nested)
					if err != nil {
						return nil, err
					}
					out[key] = merged
					continue
				}
			}
			out[key] = value
		}
	}
	return out, nil
}

func collPick(v any, keys ...string) (map[string]any, error) {
	m, ok := normalizeYAML(v).(map[string]any)
	if !ok {
		return nil, fmt.Errorf("coll.Pick requires a map")
	}
	out := map[string]any{}
	for _, key := range keys {
		if value, ok := m[key]; ok {
			out[key] = value
		}
	}
	return out, nil
}

func collOmit(v any, keys ...string) (map[string]any, error) {
	m, ok := normalizeYAML(v).(map[string]any)
	if !ok {
		return nil, fmt.Errorf("coll.Omit requires a map")
	}
	out := map[string]any{}
	blocked := map[string]struct{}{}
	for _, key := range keys {
		blocked[key] = struct{}{}
	}
	for key, value := range m {
		if _, ok := blocked[key]; !ok {
			out[key] = value
		}
	}
	return out, nil
}

func collSet(v any, key string, value any) (map[string]any, error) {
	m, ok := normalizeYAML(v).(map[string]any)
	if !ok {
		return nil, fmt.Errorf("coll.Set requires a map")
	}
	m[key] = value
	return m, nil
}

func collUnset(v any, key string) (map[string]any, error) {
	m, ok := normalizeYAML(v).(map[string]any)
	if !ok {
		return nil, fmt.Errorf("coll.Unset requires a map")
	}
	delete(m, key)
	return m, nil
}

