	if err := yaml.Unmarshal([]byte(input), &out); err != nil {
		return nil, err
	}
	return normalizeYAML(out), nil
}

func dataYAMLArray(input string) ([]any, error) {
	out, err := dataYAML(input)
	if err != nil {
		return nil, err
	}
	items, ok := out.([]any)
	if !ok {
		return nil, fmt.Errorf("YAML input is not an array")
	}
	return items, nil
}

func dataTOML(input string) (any, error) {
	var out any
	if err := toml.Unmarshal([]byte(input), &out); err != nil {
		return nil, err
	}
	return out, nil
}

func dataCSV(input string) ([][]string, error) {
	return csv.NewReader(strings.NewReader(input)).ReadAll()
}

func dataCSVByColumn(input string) (map[string][]string, error) {
	rows, err := dataCSV(input)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return map[string][]string{}, nil
	}
	headers := rows[0]
	out := map[string][]string{}
	for _, header := range headers {
		out[header] = nil
	}
	for _, row := range rows[1:] {
		for i, header := range headers {
			if i < len(row) {
				out[header] = append(out[header], row[i])
			}
		}
	}
	return out, nil
}

func dataToJSON(v any) (string, error) {
	data, err := json.Marshal(v)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func dataToJSONPretty(args ...any) (string, error) {
	indent := "  "
	value := any(nil)
	switch len(args) {
	case 1:
		value = args[0]
	case 2:
		indent = fmt.Sprint(args[0])
		value = args[1]
	default:
		return "", fmt.Errorf("toJSONPretty requires 1 or 2 arguments")
	}
	data, err := json.MarshalIndent(value, "", indent)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func dataToYAML(v any) (string, error) {
	data, err := yaml.Marshal(v)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func dataToTOML(v any) (string, error) {
	data, err := toml.Marshal(v)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func dataToCSV(v any) (string, error) {
	rows, err := toStringRows(v)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	w := csv.NewWriter(&buf)
	w.UseCRLF = true
	if err := w.WriteAll(rows); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func stringsIndent(args ...any) (string, error) {
	if len(args) == 0 || len(args) > 3 {
		return "", fmt.Errorf("strings.Indent requires 1 to 3 arguments")
	}
	width := 1
	indent := " "
	input := ""
	switch len(args) {
	case 1:
		input = fmt.Sprint(args[0])
	case 2:
		input = fmt.Sprint(args[1])
		switch first := args[0].(type) {
		case string:
			indent = first
		default:
			var err error
			width, err = toInt(first)
			if err != nil {
				return "", err
			}
		}
	case 3:
		var err error
		width, err = toInt(args[0])
		if err != nil {
			return "", err
		}
		indent = fmt.Sprint(args[1])
		input = fmt.Sprint(args[2])
	}
	if width <= 0 {
		return "", fmt.Errorf("width must be greater than 0")
	}
	if strings.Contains(indent, "\n") {
		return "", fmt.Errorf("indent must not contain a newline")
	}
	prefix := strings.Repeat(indent, width)
	lines := strings.Split(input, "\n")
	for i, line := range lines {
		lines[i] = prefix + line
	}
	return strings.Join(lines, "\n"), nil
}

func stringsSkipLines(skip any, input string) (string, error) {
	n, err := toInt(skip)
	if err != nil {
		return "", err
	}
	if n <= 0 {
		return input, nil
	}
	lines := strings.Split(input, "\n")
	if n >= len(lines) {
		return "", nil
	}
	return strings.Join(lines[n:], "\n"), nil
}

func stringsSplitN(args ...any) ([]string, error) {
	if len(args) != 3 {
		return nil, fmt.Errorf("strings.SplitN requires 3 arguments")
	}
	var n int
	var sep string
	var input string
	if _, ok := args[0].(int); ok {
		n, _ = toInt(args[0])
		sep = fmt.Sprint(args[1])
		input = fmt.Sprint(args[2])
	} else {
		sep = fmt.Sprint(args[0])
		n, _ = toInt(args[1])
		input = fmt.Sprint(args[2])
	}
	return strings.SplitN(input, sep, n), nil
}

func stringsAbbrev(args ...any) (string, error) {
	switch len(args) {
	case 2:
		width, err := toInt(args[0])
		if err != nil {
			return "", err
		}
		return abbreviate(0, width, fmt.Sprint(args[1])), nil
	case 3:
		offset, err := toInt(args[0])
		if err != nil {
			return "", err
		}
		width, err := toInt(args[1])
		if err != nil {
			return "", err
		}
		return abbreviate(offset, width, fmt.Sprint(args[2])), nil
	default:
		return "", fmt.Errorf("strings.Abbrev requires 2 or 3 arguments")
	}
}

func abbreviate(offset, width int, input string) string {
	runes := []rune(input)
	if width <= 0 || len(runes) <= width {
		return input
	}
	if offset <= 0 {
		if width <= 3 {
			return string(runes[:width])
		}
		return string(runes[:width-3]) + "..."
	}
	if width <= 6 || offset < 4 || offset >= len(runes) {
		return truncateRunes(input, width)
	}
	visible := width - 6
	if visible <= 0 {
		return truncateRunes(input, width)
	}
	end := offset + visible
	if end > len(runes) {
		end = len(runes)
	}
	return "..." + string(runes[offset:end]) + "..."
}

func truncateRunes(input string, width int) string {
	if width <= 0 {
		return ""
	}
	runes := []rune(input)
	if len(runes) <= width {
		return input
	}
	return string(runes[:width])
}

func stringsSlug(input string) string {
	input = strings.ToLower(titleCaser.String(input))
	var out []rune
	lastDash := false
	for _, r := range input {
		switch {
		case unicode.IsLetter(r) || unicode.IsDigit(r):
			out = append(out, unicode.ToLower(r))
			lastDash = false
		case !lastDash:
			out = append(out, '-')
			lastDash = true
		}
	}
	return strings.Trim(string(out), "-")
}

func singleQuote(input string) string {
	return "'" + strings.ReplaceAll(input, "'", `'\''`) + "'"
}

func shellQuote(input string) string {
	return singleQuote(input)
}

func fileWalk(root string) ([]string, error) {
	var out []string
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		out = append(out, path)
		return nil
	})
	return out, err
}

func fileWrite(filename string, data any) (string, error) {
	if !withinWorkingDir(filename) {
		cwd, _ := os.Getwd()
		return "", fmt.Errorf("path %s not contained by working directory %s", filename, cwd)
	}
	if err := os.MkdirAll(filepath.Dir(filename), 0o755); err != nil {
		return "", err
	}
	var bytes []byte
	switch x := data.(type) {
	case []byte:
		bytes = x
	default:
		bytes = []byte(fmt.Sprint(data))
	}
	if err := os.WriteFile(filename, bytes, 0o644); err != nil {
		return "", err
	}
	return "", nil
}

func testAssert(cond bool, msg ...string) (string, error) {
	if cond {
		return "", nil
	}
	if len(msg) == 0 {
		return "", fmt.Errorf("assertion failed")
	}
	return "", fmt.Errorf(strings.Join(msg, " "))
}

func testFail(msg ...string) (string, error) {
	if len(msg) == 0 {
		return "", fmt.Errorf("failure requested")
	}
	return "", fmt.Errorf(strings.Join(msg, " "))
}

func testIsKind(kind string, v any) bool {
	return testKind(v) == kind
}

func testKind(v any) string {
	if v == nil {
		return "invalid"
	}
	return reflect.TypeOf(v).Kind().String()
}

func testRequired(v any) (any, error) {
	if isEmptyValue(v) {
		return nil, fmt.Errorf("can not render template: a required value was not set")
	}
	return v, nil
}

func timeParse(args ...any) (time.Time, error) {
	switch len(args) {
	case 1:
		return time.Parse(time.RFC3339, fmt.Sprint(args[0]))
	case 2:
		return time.Parse(fmt.Sprint(args[0]), fmt.Sprint(args[1]))
	default:
		return time.Time{}, fmt.Errorf("time.Parse requires 1 or 2 arguments")
	}
}

func timeParseLocal(args ...any) (time.Time, error) {
	switch len(args) {
	case 1:
		return time.ParseInLocation(time.RFC3339, fmt.Sprint(args[0]), time.Local)
	case 2:
		return time.ParseInLocation(fmt.Sprint(args[0]), fmt.Sprint(args[1]), time.Local)
	default:
		return time.Time{}, fmt.Errorf("time.ParseLocal requires 1 or 2 arguments")
	}
}

func timeParseInLocation(location, layout, input string) (time.Time, error) {
	loc, err := time.LoadLocation(location)
	if err != nil {
		return time.Time{}, err
	}
	return time.ParseInLocation(layout, input, loc)
}

func timeUnix(args ...any) (time.Time, error) {
	switch len(args) {
	case 1:
		sec, err := toInt64(args[0])
		if err != nil {
			return time.Time{}, err
		}
		return time.Unix(sec, 0), nil
	case 2:
		sec, err := toInt64(args[0])
		if err != nil {
			return time.Time{}, err
		}
		nsec, err := toInt64(args[1])
		if err != nil {
			return time.Time{}, err
		}
		return time.Unix(sec, nsec), nil
	default:
		return time.Time{}, fmt.Errorf("time.Unix requires 1 or 2 arguments")
	}
}

func netParseAddr(s string) (netip.Addr, error) {
	addr, err := netip.ParseAddr(s)
	if err != nil {
		return netip.Addr{}, fmt.Errorf("ParseAddr(%q): unable to parse IP", s)
	}
	return addr, nil
}

func netParsePrefix(s string) (netip.Prefix, error) {
	prefix, err := netip.ParsePrefix(s)
	if err != nil {
		return netip.Prefix{}, fmt.Errorf("ParsePrefix(%q): unable to parse IP prefix", s)
	}
	return prefix, nil
}

type ipRange struct {
	From netip.Addr
	To   netip.Addr
}

func (r ipRange) String() string {
	return r.From.String() + "-" + r.To.String()
}

func netParseRange(s string) (ipRange, error) {
	parts := strings.SplitN(s, "-", 2)
	if len(parts) != 2 {
		return ipRange{}, fmt.Errorf("ParseRange(%q): unable to parse IP range", s)
	}
	from, err := netip.ParseAddr(parts[0])
	if err != nil {
		return ipRange{}, fmt.Errorf("ParseRange(%q): unable to parse IP range", s)
	}
	to, err := netip.ParseAddr(parts[1])
	if err != nil {
		return ipRange{}, fmt.Errorf("ParseRange(%q): unable to parse IP range", s)
	}
	return ipRange{From: from, To: to}, nil
}

func experimentalFunc(name string) func(...any) (any, error) {
	return func(args ...any) (any, error) {
		return nil, fmt.Errorf("%s: experimental function, but experimental mode not enabled", name)
	}
}

func semverCheckConstraint(constraint string, version any) (bool, error) {
	c, err := semverpkg.NewConstraint(constraint)
	if err != nil {
		return false, err
	}
	var v *semverpkg.Version
	switch x := version.(type) {
	case *semverpkg.Version:
		v = x
	case string:
		v, err = semverpkg.NewVersion(x)
	default:
		v, err = semverpkg.NewVersion(fmt.Sprint(version))
	}
	if err != nil {
		return false, err
	}
	return c.Check(v), nil
}

func toSlice(v any) ([]any, error) {
	switch x := v.(type) {
	case []any:
		return append([]any(nil), x...), nil
	case []string:
		out := make([]any, len(x))
		for i, item := range x {
			out[i] = item
		}
		return out, nil
	case []int:
		out := make([]any, len(x))
		for i, item := range x {
			out[i] = item
		}
		return out, nil
	case []int64:
		out := make([]any, len(x))
		for i, item := range x {
			out[i] = item
		}
		return out, nil
	case []float64:
		out := make([]any, len(x))
		for i, item := range x {
			out[i] = item
		}
		return out, nil
	}
	rv := reflect.ValueOf(v)
	if !rv.IsValid() {
		return nil, nil
	}
	if rv.Kind() != reflect.Slice && rv.Kind() != reflect.Array {
		return nil, fmt.Errorf("value is not a slice")
	}
	out := make([]any, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		out[i] = rv.Index(i).Interface()
	}
	return out, nil
}

func toStringSlice(v any) ([]string, error) {
	items, err := toSlice(v)
	if err != nil {
		return nil, err
	}
	out := make([]string, len(items))
	for i, item := range items {
		out[i] = fmt.Sprint(item)
	}
	return out, nil
}

func toStringRows(v any) ([][]string, error) {
	items, err := toSlice(v)
	if err != nil {
		return nil, err
	}
	rows := make([][]string, len(items))
	for i, item := range items {
		rows[i], err = toStringSlice(item)
		if err != nil {
			return nil, err
		}
	}
	return rows, nil
}

func isEmptyValue(v any) bool {
	if v == nil {
		return true
	}
	switch x := v.(type) {
	case string:
		return x == ""
	case bool:
		return !x
	case int, int8, int16, int32, int64:
		return reflect.ValueOf(v).Int() == 0
	case uint, uint8, uint16, uint32, uint64:
		return reflect.ValueOf(v).Uint() == 0
	case float32, float64:
		return reflect.ValueOf(v).Float() == 0
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Array, reflect.Map, reflect.Slice, reflect.String:
		return rv.Len() == 0
	case reflect.Bool:
		return !rv.Bool()
	case reflect.Interface, reflect.Pointer:
		return rv.IsNil()
	}
	return false
}

