package main

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func execute(ctx context.Context, opts *resolvedOptions, logger *slog.Logger) error {
	logger.Debug("starting gomplate", slog.Any("config", opts))

	stdinData, err := gatherAllStdin(needsStdin(opts))
	if err != nil {
		return &quietError{err: err}
	}

	manager := newDatasourceManager(logger)
	manager.SetStdin(stdinData)
	for _, spec := range opts.datasources {
		if err := manager.AddSpec(spec); err != nil {
			return err
		}
	}
	for _, spec := range opts.contexts {
		if err := manager.AddContextSpec(spec); err != nil {
			return err
		}
	}
	for _, spec := range opts.datasourceHeaders {
		if err := manager.AddHeaderSpec(spec); err != nil {
			return err
		}
	}

	root, err := buildRootContext(ctx, manager, opts.contexts)
	if err != nil {
		return &quietError{err: err}
	}
	renderer, err := newTemplateRenderer(ctx, opts, manager, logger)
	if err != nil {
		return &quietError{err: err}
	}

	var execInput []byte
	switch {
	case strings.TrimSpace(opts.inline) != "":
		execInput, err = renderInline(ctx, opts, renderer, root)
	case opts.inputDir != "":
		err = renderDirectory(ctx, opts, renderer, root)
	default:
		execInput, err = renderFiles(ctx, opts, renderer, root, stdinData)
	}
	if err != nil {
		return &quietError{err: err}
	}

	if len(opts.postExec) > 0 {
		if err := runPostExec(ctx, opts, execInput); err != nil {
			return &quietError{err: err}
		}
	}

	logger.Debug("completed rendering")
	return nil
}

func needsStdin(opts *resolvedOptions) bool {
	if opts.inline == "" {
		if opts.inputDir == "" {
			for _, input := range opts.inputFiles {
				if input == "-" {
					return true
				}
			}
		}
	}
	for _, spec := range opts.datasources {
		if strings.Contains(spec, "stdin:") {
			return true
		}
	}
	for _, spec := range opts.contexts {
		if strings.Contains(spec, "stdin:") {
			return true
		}
	}
	return false
}

func renderInline(ctx context.Context, opts *resolvedOptions, renderer *templateRenderer, root any) ([]byte, error) {
	rendered, err := renderer.render(ctx, "<arg>", "<arg>", opts.inline, root)
	if err != nil {
		return nil, err
	}
	if opts.execPipe {
		return rendered, nil
	}
	return rendered, writeOutput(opts.outputFiles[0], "", opts.chmod, rendered, false)
}

func renderFiles(ctx context.Context, opts *resolvedOptions, renderer *templateRenderer, root any, stdinData []byte) ([]byte, error) {
	var first []byte
	for i, input := range opts.inputFiles {
		content, err := gatherTemplateInput(input, stdinData)
		if err != nil {
			return nil, fmt.Errorf("failed to gather templates for rendering: %w", err)
		}
		name := input
		if input == "-" {
			name = "-"
		}
		rendered, err := renderer.render(ctx, name, name, string(content), root)
		if err != nil {
			return nil, err
		}
		if i == 0 {
			first = append([]byte(nil), rendered...)
		}
		if opts.execPipe {
			continue
		}
		if err := writeOutput(opts.outputFiles[i], input, opts.chmod, rendered, false); err != nil {
			return nil, err
		}
	}
	return first, nil
}

func renderDirectory(ctx context.Context, opts *resolvedOptions, renderer *templateRenderer, root any) error {
	files, err := walkInputDir(opts.inputDir)
	if err != nil {
		return fmt.Errorf("failed to render directory: %w", err)
	}
	for _, input := range files {
		rel, err := filepath.Rel(opts.inputDir, input)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if shouldExclude(rel, opts.includes, opts.excludes) {
			continue
		}
		dest, err := directoryOutputPath(ctx, opts, renderer, root, rel)
		if err != nil {
			return err
		}
		if dest == "" {
			continue
		}
		if shouldCopyWithoutProcessing(rel, opts.excludeProcessing) {
			content, err := os.ReadFile(input)
			if err != nil {
				return err
			}
			if err := writeOutput(dest, input, opts.chmod, content, true); err != nil {
				return err
			}
			continue
		}
		content, err := os.ReadFile(input)
		if err != nil {
			return err
		}
		rendered, err := renderer.render(ctx, input, input, string(content), root)
		if err != nil {
			return err
		}
		if err := writeOutput(dest, input, opts.chmod, rendered, false); err != nil {
			return err
		}
	}
	return nil
}

func directoryOutputPath(ctx context.Context, opts *resolvedOptions, renderer *templateRenderer, root any, rel string) (string, error) {
	if opts.outputMap == "" {
		return filepath.Join(opts.outputDir, filepath.FromSlash(rel)), nil
	}

	outputRoot := map[string]any{
		"in":  rel,
		"ctx": root,
	}
	if m, ok := normalizeYAML(root).(map[string]any); ok {
		for key, value := range m {
			if key == "in" || key == "ctx" {
				continue
			}
			outputRoot[key] = value
		}
	}
	rendered, err := renderer.render(ctx, "<output-map>", "<output-map>", opts.outputMap, outputRoot)
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(rendered)), nil
}

func writeOutput(outputPath, sourcePath, chmod string, rendered []byte, copied bool) error {
	if outputPath == "-" {
		_, err := os.Stdout.Write(rendered)
		return err
	}
	if strings.TrimSpace(string(rendered)) == "" {
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(outputPath), 0o755); err != nil {
		return err
	}
	mode := os.FileMode(0o644)
	if sourcePath != "" && sourcePath != "-" {
		if info, err := os.Stat(sourcePath); err == nil {
			mode = info.Mode()
		}
	}
	if chmod != "" {
		parsed, err := strconv.ParseUint(chmod, 8, 32)
		if err != nil {
			return err
		}
		mode = os.FileMode(parsed)
	}
	return os.WriteFile(outputPath, rendered, mode)
}

func runPostExec(ctx context.Context, opts *resolvedOptions, input []byte) error {
	if len(opts.postExec) == 0 {
		return nil
	}
	cmd := exec.CommandContext(ctx, opts.postExec[0], opts.postExec[1:]...)
	if opts.execPipe {
		cmd.Stdin = strings.NewReader(string(input))
	}
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if !opts.execPipe {
		cmd.Stdin = os.Stdin
	}
	return cmd.Run()
}

