type PositionalArgs func(cmd *Command, args []string) error

func ArbitraryArgs(_ *Command, _ []string) error { return nil }

type Command struct {
	Use           string
	Short         string
	Version       string
	SilenceErrors bool
	SilenceUsage  bool
	Args          PositionalArgs
	RunE          func(cmd *Command, args []string) error

	out             io.Writer
	flags           *FlagSet
	versionTemplate string
}

func (c *Command) Flags() *FlagSet {
	if c.flags == nil {
		c.flags = newFlagSet()
	}
	return c.flags
}

func (c *Command) SetVersionTemplate(s string) {
	c.versionTemplate = s
}

func (c *Command) SetOut(w io.Writer) {
	c.out = w
}

func (c *Command) OutOrStdout() io.Writer {
	if c.out != nil {
		return c.out
	}
	return os.Stdout
}

func (c *Command) ExecuteContext(_ context.Context) error {
	if c.Args == nil {
		c.Args = ArbitraryArgs
	}
	args := os.Args[1:]
	rest, err := c.Flags().parse(args)
	if err != nil {
		return err
	}
	if c.Flags().helpRequested {
		return c.Usage()
	}
	if c.Flags().versionRequested {
		if c.versionTemplate == "" {
			c.versionTemplate = "{{.Version}}\n"
		}
		_, err := io.WriteString(c.OutOrStdout(), strings.ReplaceAll(c.versionTemplate, "{{.Version}}", c.Version))
		return err
	}
	if err := c.Args(c, rest); err != nil {
		return err
	}
	if c.RunE == nil {
		return nil
	}
	return c.RunE(c, rest)
}

func (c *Command) Usage() error {
	_, err := io.WriteString(c.OutOrStdout(), c.Flags().usage(c))
	return err
}

type FlagSet struct {
	defs             []*Flag
	byName           map[string]*Flag
	byShort          map[string]*Flag
	SortFlags        bool
	helpRequested    bool
	versionRequested bool
}

type Flag struct {
	Name      string
	Short     string
	Usage     string
	Type      string
	String    *string
	Bool      *bool
	Strings   *[]string
	Default   string
	Defaults  []string
	Changed   bool
}

func newFlagSet() *FlagSet {
	return &FlagSet{
		byName:  map[string]*Flag{},
		byShort: map[string]*Flag{},
	}
}

func (f *FlagSet) add(flag *Flag) {
	f.defs = append(f.defs, flag)
	f.byName[flag.Name] = flag
	if flag.Short != "" {
		f.byShort[flag.Short] = flag
	}
}

func (f *FlagSet) StringSliceVarP(target *[]string, name, short string, value []string, usage string) {
	*target = append([]string(nil), value...)
	f.add(&Flag{Name: name, Short: short, Usage: usage, Type: "strings", Strings: target, Defaults: append([]string(nil), value...)})
}

func (f *FlagSet) StringSliceVar(target *[]string, name string, value []string, usage string) {
	f.StringSliceVarP(target, name, "", value, usage)
}

func (f *FlagSet) StringVarP(target *string, name, short, value, usage string) {
	*target = value
	f.add(&Flag{Name: name, Short: short, Usage: usage, Type: "string", String: target, Default: value})
}

func (f *FlagSet) StringVar(target *string, name, value, usage string) {
	f.StringVarP(target, name, "", value, usage)
}

func (f *FlagSet) BoolVarP(target *bool, name, short string, value bool, usage string) {
	*target = value
	f.add(&Flag{Name: name, Short: short, Usage: usage, Type: "bool", Bool: target, Default: fmt.Sprint(value)})
}

func (f *FlagSet) BoolVar(target *bool, name string, value bool, usage string) {
	f.BoolVarP(target, name, "", value, usage)
}

func (f *FlagSet) Changed(name string) bool {
	flag := f.byName[name]
	return flag != nil && flag.Changed
}

func (f *FlagSet) parse(args []string) ([]string, error) {
	var rest []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			rest = append(rest, args[i+1:]...)
			break
		}
		if arg == "-h" || arg == "--help" {
			f.helpRequested = true
			return nil, nil
		}
		if arg == "-v" || arg == "--version" {
			f.versionRequested = true
			return nil, nil
		}
		if !strings.HasPrefix(arg, "-") || arg == "-" {
			rest = append(rest, args[i:]...)
			break
		}

		var flag *Flag
		var value string
		var hasValue bool
		if strings.HasPrefix(arg, "--") {
			name := strings.TrimPrefix(arg, "--")
			if eq := strings.IndexByte(name, '='); eq >= 0 {
				value = name[eq+1:]
				name = name[:eq]
				hasValue = true
			}
			flag = f.byName[name]
			if flag == nil {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
		} else {
			name := strings.TrimPrefix(arg, "-")
			if eq := strings.IndexByte(name, '='); eq >= 0 {
				value = name[eq+1:]
				name = name[:eq]
				hasValue = true
			}
			flag = f.byShort[name]
			if flag == nil {
				return nil, fmt.Errorf("unknown shorthand flag: %q in -%s", name, name)
			}
		}

		switch flag.Type {
		case "bool":
			if hasValue {
				*flag.Bool = value == "true"
			} else {
				*flag.Bool = true
			}
			flag.Changed = true
		case "string":
			if !hasValue {
				i++
				if i >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: --%s", flag.Name)
				}
				value = args[i]
			}
			*flag.String = value
			flag.Changed = true
		case "strings":
			if !hasValue {
				i++
				if i >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: --%s", flag.Name)
				}
				value = args[i]
			}
			if !flag.Changed {
				*flag.Strings = []string{}
			}
			*flag.Strings = append(*flag.Strings, value)
			flag.Changed = true
		}
	}
	return rest, nil
}

func (f *FlagSet) usage(cmd *Command) string {
	lines := []string{
		cmd.Short,
		"",
		"Usage:",
		"  " + cmd.Use + " [flags]",
		"",
		"Flags:",
	}
	for _, flag := range f.defs {
		lines = append(lines, "  "+flag.usageLine())
	}
	lines = append(lines,
		"  -h, --help                         help for "+cmd.Use,
		"  -v, --version                      version for "+cmd.Use,
	)
	return strings.Join(lines, "\n") + "\n"
}

func (f *Flag) usageLine() string {
	var left string
	switch {
	case f.Short != "" && f.Type == "string":
		left = fmt.Sprintf("-%s, --%s %s", f.Short, f.Name, placeholder(f.Name))
	case f.Short != "" && f.Type == "strings":
		left = fmt.Sprintf("-%s, --%s %s", f.Short, f.Name, placeholder(f.Name))
	case f.Short != "" && f.Type == "bool":
		left = fmt.Sprintf("-%s, --%s", f.Short, f.Name)
	case f.Type == "string":
		left = fmt.Sprintf("    --%s %s", f.Name, placeholder(f.Name))
	case f.Type == "strings":
		left = fmt.Sprintf("    --%s %s", f.Name, placeholder(f.Name))
	default:
		left = fmt.Sprintf("    --%s", f.Name)
	}
	right := f.Usage
	switch {
	case f.Type == "string" && f.Default != "":
		right += fmt.Sprintf(" (default %q)", f.Default)
	case f.Type == "strings" && len(f.Defaults) > 0:
		right += fmt.Sprintf(" (default [%s])", strings.Join(f.Defaults, " "))
	}
	return fmt.Sprintf("%-34s %s", left, right)
}

func placeholder(name string) string {
	switch name {
	case "datasource":
		return "datasource"
	case "datasource-header":
		return "header"
	case "context":
		return "datasource"
	case "plugin":
		return "strings"
	case "file":
		return "file"
	case "out":
		return "file"
	case "template":
		return "strings"
	case "input-dir", "output-dir":
		return "directory"
	case "output-map":
		return "string"
	case "left-delim", "right-delim":
		return "delimiter"
	case "missing-key":
		return "string"
	case "config":
		return "string"
	default:
		return "string"
	}
}

