		"snakecase": snakeCase,
		"kebabcase": kebabCase,
		"wrap":      wrap,
	}
}

func defaultFunc(def, v any) any {
	if isEmpty(v) {
		return def
	}
	return v
}

func ternary(trueVal, falseVal any, cond bool) any {
	if cond {
		return trueVal
	}
	return falseVal
}

func fail(msg string) (string, error) {
	return "", fmt.Errorf(msg)
}

func camelCase(input string) string {
	words := splitWords(input)
	for i := range words {
		words[i] = strings.Title(words[i])
	}
	return strings.Join(words, "")
}

func snakeCase(input string) string {
	return strings.Join(splitWords(input), "_")
}

func kebabCase(input string) string {
	return strings.Join(splitWords(input), "-")
}

func wrap(width int, input string) string {
	if width <= 0 {
		return input
	}
	words := strings.Fields(input)
	if len(words) == 0 {
		return ""
	}
	var lines []string
	line := words[0]
	for _, word := range words[1:] {
		if len([]rune(line))+1+len([]rune(word)) > width {
			lines = append(lines, line)
			line = word
			continue
		}
		line += " " + word
	}
	lines = append(lines, line)
	return strings.Join(lines, "\n")
}

func splitWords(input string) []string {
	input = strings.TrimSpace(input)
	if input == "" {
		return nil
	}
	var words []string
	var current []rune
	for _, r := range input {
