package simpleuuid

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net"
	"strings"
	"time"
)

type UUID [16]byte

var Nil UUID

func New() UUID {
	var u UUID
	_, _ = io.ReadFull(rand.Reader, u[:])
	u[6] = (u[6] & 0x0f) | 0x40
	u[8] = (u[8] & 0x3f) | 0x80
	return u
}

func NewUUID() (UUID, error) {
	var u UUID
	t := time.Now().UTC().UnixNano()/100 + 0x01B21DD213814000
	u[0] = byte(t >> 24)
	u[1] = byte(t >> 16)
	u[2] = byte(t >> 8)
	u[3] = byte(t)
	u[4] = byte(t >> 40)
	u[5] = byte(t >> 32)
	u[6] = byte(t>>56)&0x0f | 0x10
	u[7] = byte(t >> 48)
	_, _ = io.ReadFull(rand.Reader, u[8:10])
	u[8] = (u[8] & 0x3f) | 0x80
	if ifaces, err := net.Interfaces(); err == nil {
		for _, iface := range ifaces {
			if len(iface.HardwareAddr) >= 6 {
				copy(u[10:], iface.HardwareAddr[:6])
				return u, nil
			}
		}
	}
	_, err := io.ReadFull(rand.Reader, u[10:])
	return u, err
}

func Parse(s string) (UUID, error) {
	var u UUID
	s = strings.ToLower(strings.TrimSpace(s))
	s = strings.ReplaceAll(s, "-", "")
	if len(s) != 32 {
		return u, fmt.Errorf("invalid UUID length")
	}
	data, err := hex.DecodeString(s)
	if err != nil {
		return u, err
	}
	copy(u[:], data)
	return u, nil
}

func Validate(s string) error {
	_, err := Parse(s)
	return err
}

func (u UUID) String() string {
	var buf [36]byte
	hex.Encode(buf[0:8], u[0:4])
	buf[8] = '-'
	hex.Encode(buf[9:13], u[4:6])
	buf[13] = '-'
	hex.Encode(buf[14:18], u[6:8])
	buf[18] = '-'
	hex.Encode(buf[19:23], u[8:10])
	buf[23] = '-'
	hex.Encode(buf[24:36], u[10:16])
	return string(buf[:])
}

