package simpletoml

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

func Unmarshal(data []byte, out any) error {
	root := map[string]any{}
	current := root
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			path := strings.Split(strings.Trim(line, "[]"), ".")
			current = root
			for _, part := range path {
				next, ok := current[part].(map[string]any)
				if !ok {
					next = map[string]any{}
					current[part] = next
				}
				current = next
			}
			continue
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			return fmt.Errorf("invalid TOML line %q", line)
		}
		current[strings.TrimSpace(key)] = parseValue(strings.TrimSpace(value))
	}
	dataJSON, err := json.Marshal(root)
	if err != nil {
		return err
	}
	return json.Unmarshal(dataJSON, out)
}

func Marshal(v any) ([]byte, error) {
	root, ok := normalize(v).(map[string]any)
	if !ok {
		return nil, fmt.Errorf("TOML marshal requires a map")
	}
	var buf bytes.Buffer
	if err := writeMap(&buf, nil, root); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func writeMap(buf *bytes.Buffer, prefix []string, m map[string]any) error {
	keys := make([]string, 0, len(m))
	for key := range m {
		keys = append(keys, key)
	}
	sort.Strings(keys)
