		return i
	}
	if f, err := strconv.ParseFloat(raw, 64); err == nil {
		return f
	}
	return raw
}

func formatValue(v any) string {
	switch x := v.(type) {
	case string:
		return strconv.Quote(x)
	case bool:
		if x {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprint(v)
	}
}

func normalize(v any) any {
	switch x := v.(type) {
	case map[string]any:
		for key, value := range x {
			x[key] = normalize(value)
		}
		return x
	case map[any]any:
		out := map[string]any{}
		for key, value := range x {
			out[fmt.Sprint(key)] = normalize(value)
		}
		return out
	default:
		return v
	}
}

