package simpleyaml

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

func Unmarshal(data []byte, out any) error {
	value, err := parse(string(data))
	if err != nil {
		return err
	}
	if p, ok := out.(*any); ok {
		*p = value
		return nil
	}
	j, err := json.Marshal(value)
	if err != nil {
		return err
	}
	return json.Unmarshal(j, out)
}

func Marshal(v any) ([]byte, error) {
	var buf bytes.Buffer
	writeValue(&buf, 0, normalize(v))
	return buf.Bytes(), nil
}

func writeValue(buf *bytes.Buffer, indent int, v any) {
	switch x := v.(type) {
	case map[string]any:
		keys := make([]string, 0, len(x))
		for key := range x {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			writeIndent(buf, indent)
			buf.WriteString(key)
			switch value := x[key].(type) {
			case map[string]any, []any:
				buf.WriteString(":\n")
				writeValue(buf, indent+2, value)
			default:
				buf.WriteString(": ")
				buf.WriteString(formatScalar(value))
				buf.WriteByte('\n')
			}
		}
	case []any:
		for _, item := range x {
			writeIndent(buf, indent)
			buf.WriteString("-")
			switch value := item.(type) {
			case map[string]any, []any:
				buf.WriteByte('\n')
				writeValue(buf, indent+2, value)
			default:
				buf.WriteByte(' ')
				buf.WriteString(formatScalar(value))
				buf.WriteByte('\n')
			}
		}
	default:
		writeIndent(buf, indent)
		buf.WriteString(formatScalar(x))
		buf.WriteByte('\n')
	}
}

func parse(input string) (any, error) {
	lines := splitLines(input)
	index := 0
	return parseBlock(lines, &index, 0)
}

type line struct {
	indent  int
	content string
}

func splitLines(input string) []line {
	rawLines := strings.Split(strings.ReplaceAll(input, "\r\n", "\n"), "\n")
	lines := make([]line, 0, len(rawLines))
	for _, raw := range rawLines {
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		indent := len(raw) - len(strings.TrimLeft(raw, " "))
		lines = append(lines, line{indent: indent, content: strings.TrimSpace(raw)})
	}
	return lines
}

func parseBlock(lines []line, index *int, indent int) (any, error) {
	if *index >= len(lines) {
		return map[string]any{}, nil
	}
	if strings.HasPrefix(lines[*index].content, "- ") && lines[*index].indent == indent {
		return parseSeq(lines, index, indent)
	}
	return parseMap(lines, index, indent)
}

func parseSeq(lines []line, index *int, indent int) ([]any, error) {
	var out []any
	for *index < len(lines) {
		line := lines[*index]
		if line.indent < indent || !strings.HasPrefix(line.content, "- ") || line.indent != indent {
			break
		}
		itemContent := strings.TrimSpace(strings.TrimPrefix(line.content, "- "))
		*index++
		if itemContent == "" {
			value, err := parseBlock(lines, index, indent+2)
			if err != nil {
				return nil, err
			}
			out = append(out, value)
			continue
		}
		if isKeyValue(itemContent) {
			key, raw, _ := strings.Cut(itemContent, ":")
			m := map[string]any{}
			if strings.TrimSpace(raw) == "" {
				value, err := parseBlock(lines, index, indent+2)
				if err != nil {
					return nil, err
				}
				m[strings.TrimSpace(key)] = value
			} else {
				m[strings.TrimSpace(key)] = parseInline(strings.TrimSpace(raw))
			}
			for *index < len(lines) && lines[*index].indent > indent {
				subIndent := lines[*index].indent
				if subIndent < indent+2 {
					break
				}
				key, raw, _ := strings.Cut(lines[*index].content, ":")
				*index++
				if strings.TrimSpace(raw) == "" {
					value, err := parseBlock(lines, index, subIndent+2)
					if err != nil {
						return nil, err
					}
					m[strings.TrimSpace(key)] = value
				} else {
					m[strings.TrimSpace(key)] = parseInline(strings.TrimSpace(raw))
				}
			}
			out = append(out, m)
			continue
		}
		out = append(out, parseInline(itemContent))
	}
	return out, nil
}

func parseMap(lines []line, index *int, indent int) (map[string]any, error) {
	out := map[string]any{}
	for *index < len(lines) {
		line := lines[*index]
		if line.indent < indent || line.indent != indent || strings.HasPrefix(line.content, "- ") {
			break
		}
		key, raw, ok := strings.Cut(line.content, ":")
		if !ok {
			return nil, fmt.Errorf("invalid YAML line %q", line.content)
		}
		key = strings.TrimSpace(key)
		raw = strings.TrimSpace(raw)
		*index++
		switch {
		case raw == "|":
			block, err := parseLiteral(lines, index, indent+2)
			if err != nil {
				return nil, err
			}
			out[key] = block
		case raw == "":
			value, err := parseBlock(lines, index, indent+2)
			if err != nil {
				return nil, err
			}
			out[key] = value
		default:
			out[key] = parseInline(raw)
		}
	}
	return out, nil
}

func parseLiteral(lines []line, index *int, indent int) (string, error) {
	var parts []string
	for *index < len(lines) {
		line := lines[*index]
		if line.indent < indent {
			break
		}
		parts = append(parts, strings.Repeat(" ", line.indent-indent)+line.content)
		*index++
	}
	if len(parts) == 0 {
		return "", nil
	}
	return strings.Join(parts, "\n") + "\n", nil
}

func parseInline(raw string) any {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}
	if strings.HasPrefix(raw, "{") && strings.HasSuffix(raw, "}") {
		m := map[string]any{}
		for _, part := range splitTopLevel(raw[1:len(raw)-1], ',') {
			key, value, ok := splitTopLevelKV(part, ':')
			if ok {
				m[strings.TrimSpace(key)] = parseInline(value)
			}
		}
		return m
	}
	if strings.HasPrefix(raw, "[") && strings.HasSuffix(raw, "]") {
		var out []any
		for _, part := range splitTopLevel(raw[1:len(raw)-1], ',') {
			out = append(out, parseInline(part))
		}
		return out
	}
	if len(raw) >= 2 && ((raw[0] == '"' && raw[len(raw)-1] == '"') || (raw[0] == '\'' && raw[len(raw)-1] == '\'')) {
		return strings.Trim(raw, `"'`)
	}
	switch raw {
	case "true":
		return true
	case "false":
		return false
	case "null", "~":
		return nil
	}
	if i, err := strconv.ParseInt(raw, 0, 64); err == nil {
		return i
	}
	if f, err := strconv.ParseFloat(raw, 64); err == nil {
		return f
	}
	return raw
}

func splitTopLevel(s string, sep rune) []string {
	var parts []string
	start := 0
	depth := 0
	var quote rune
	for i, r := range s {
		switch {
		case quote != 0:
			if r == quote {
				quote = 0
			}
		case r == '"' || r == '\'':
			quote = r
		case r == '{' || r == '[':
			depth++
		case r == '}' || r == ']':
			depth--
		case r == sep && depth == 0:
			parts = append(parts, strings.TrimSpace(s[start:i]))
			start = i + 1
		}
	}
	parts = append(parts, strings.TrimSpace(s[start:]))
	return parts
}

func splitTopLevelKV(s string, sep rune) (string, string, bool) {
	depth := 0
	var quote rune
	for i, r := range s {
		switch {
		case quote != 0:
			if r == quote {
				quote = 0
			}
		case r == '"' || r == '\'':
			quote = r
		case r == '{' || r == '[':
			depth++
		case r == '}' || r == ']':
			depth--
		case r == sep && depth == 0:
			return strings.TrimSpace(s[:i]), strings.TrimSpace(s[i+1:]), true
		}
	}
	return "", "", false
}

func isKeyValue(s string) bool {
	_, _, ok := splitTopLevelKV(s, ':')
	return ok
}

func formatScalar(v any) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case string:
		if x == "" {
			return `""`
		}
		if strings.ContainsAny(x, ":\n#{}[],\"'") || strings.HasPrefix(x, " ") || strings.HasSuffix(x, " ") {
			return strconv.Quote(x)
		}
		return x
	case bool:
		if x {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprint(v)
	}
}

func writeIndent(buf *bytes.Buffer, indent int) {
	for i := 0; i < indent; i++ {
		buf.WriteByte(' ')
	}
}

func normalize(v any) any {
	switch x := v.(type) {
	case map[string]any:
		for key, value := range x {
			x[key] = normalize(value)
		}
		return x
	case map[any]any:
		out := map[string]any{}
		for key, value := range x {
			out[fmt.Sprint(key)] = normalize(value)
		}
		return out
	case []any:
		for i, value := range x {
			x[i] = normalize(value)
		}
		return x
	default:
		return v
	}
}
